import { useMemo, useState } from 'react';
import { DatabaseBackup, Download, FileUp, UploadCloud } from 'lucide-react';
import { useBusinessCrm } from '../BusinessCrmContext';
import { crmApi, messageFromError } from '../api';
import { Button, Card, Field, PageHeader, Select, Table } from '../components/ui';
const templates={clients:'name,whatsapp,email,company,address,tax_id,notes,status\nExample Client,923001234567,client@example.com,Example Co,,,Priority account,active\n',vendors:'name,whatsapp,email,company,address,tax_id,notes,status\nExample Vendor,923009876543,vendor@example.com,Vendor Co,,,Primary supplier,active\n',products:'name,category,account_type,duration_label,default_sale_price,default_purchase_cost,currency_code,active,notes\nCanva Pro,Software,private,1 Month,1000.00,600.00,PKR,true,\n'};
function downloadText(filename,text,type='text/csv'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url)}
export default function ImportsPage(){const crm=useBusinessCrm();const[kind,setKind]=useState('clients');const[file,setFile]=useState(null);const[result,setResult]=useState(null);const[error,setError]=useState('');const[busy,setBusy]=useState(false);const rows=useMemo(()=>result?.errors||[],[result]);const upload=async()=>{if(!file)return;setBusy(true);setError('');setResult(null);try{const text=await file.text();const response=await crmApi.post(`/admin/imports/${kind}`,text,{headers:{'Content-Type':'text/csv'}});setResult(response.data)}catch(e){setError(messageFromError(e))}finally{setBusy(false)}};return <><PageHeader title="Imports, exports & backup" description="Validated CSV onboarding plus operational exports and encrypted-field backup."/>{error&&<div className="bcrm-banner warning">{error}</div>}<div className="bcrm-grid bcrm-grid-2"><Card title="CSV import" subtitle="Up to 2,000 rows; invalid rows are reported without discarding valid ones"><div className="bcrm-form"><Field label="Record type"><Select value={kind} onChange={e=>{setKind(e.target.value);setFile(null);setResult(null)}}><option value="clients">Clients</option><option value="vendors">Vendors</option><option value="products">Products</option></Select></Field><Field label="CSV file"><input className="bcrm-input" type="file" accept=".csv,text/csv" onChange={e=>setFile(e.target.files?.[0]||null)}/></Field><div className="bcrm-form-actions"><Button variant="secondary" icon={Download} onClick={()=>downloadText(`${kind}-template.csv`,templates[kind])}>Template</Button><Button icon={UploadCloud} onClick={upload} disabled={!file||busy}>{busy?'Importing…':'Import CSV'}</Button></div>{result&&<div className="bcrm-banner">Run {result.runId}: {result.imported} imported, {result.rejected} rejected from {result.total} rows.</div>}{rows.length>0&&<Table rows={rows} rowKey="row" columns={[{key:'row',label:'CSV row'},{key:'error',label:'Reason'}]}/>}</div></Card><Card title="Exports & recovery" subtitle="Downloads require explicit backend permissions"><div className="bcrm-form"><p className="bcrm-banner">Credentials remain AES-GCM ciphertext in backup exports. Keep backups and vault keys in separate secure locations.</p>{crm.has('exports.download')&&<Button variant="secondary" icon={FileUp} onClick={()=>window.open(crmApi.rawUrl('/admin/exports/sales.csv'),'_blank','noopener,noreferrer')}>Download sales CSV</Button>}{crm.has('backup.download')&&<Button icon={DatabaseBackup} onClick={()=>window.open(crmApi.rawUrl('/admin/backup.json'),'_blank','noopener,noreferrer')}>Download Business CRM backup</Button>}</div></Card></div></>}
